-- UUID v7: time-ordered, generated by the database (PostgreSQL 18+)
CREATE TABLE events (
    id         uuid PRIMARY KEY DEFAULT uuidv7(),
    type       text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
-- Elsewhere: Python 3.14 uuid.uuid7(); Java/Node libraries (e.g. uuid-creator, the "uuid"
-- npm package's v7()).

-- Block allocation ("ticket server" / hi-lo): each app instance reserves 1,000 ids at a
-- time.
CREATE TABLE id_blocks (name text PRIMARY KEY, next_value bigint NOT NULL);
INSERT INTO id_blocks VALUES ('order', 1);

UPDATE id_blocks
SET next_value = next_value + 1000
WHERE name = 'order'
-- this instance now owns [start, start + 999]
RETURNING next_value - 1000 AS block_start;
-- One round trip per 1,000 ids; ids are dense and roughly increasing; a crash leaves a
-- gap.

-- A plain sequence with caching does the same inside one database:
CREATE SEQUENCE order_seq CACHE 50;
